import{z as n,x as i,o as e,c as p,q as o,j as E,D as t,d as l,s as A,S as r}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"Least-to-Most","description":"","frontmatter":{"title":"Least-to-Most","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/least-to-most.md","filePath":"llm/least-to-most.md","lastUpdated":1791063341000}'),m={name:"llm/least-to-most.md"};function d(B,a,h,_,C,T){const s=i("Mermaid");return e(),p("div",null,[a[2]||(a[2]=o('<h1 id="least-to-most" tabindex="-1">Least-to-Most <a class="header-anchor" href="#least-to-most" aria-label="Permalink to &quot;Least-to-Most&quot;">​</a></h1><div class="epigraph"><p>先把复杂问题分解成一串更简单的子问题，再从最容易的开始依次求解，后一问可以使用前面已经得到的答案。</p><footer>—— Zhou et al., Least-to-Most Prompting Enables Complex Reasoning in Large Language Models, ICLR 2023</footer></div><p><a href="/llm/graph-of-thoughts">上一课</a>用顶点存中间思维、用边表达依赖，并显式支持聚合与精炼；图在宿主里，模型只见当前操作所需的顶点文本。<a href="/llm/chain-of-thought">思维链</a>在一条连续的 \\(z\\) 里同时做分解与计算，组合深度一增加就既要拆对又要算对。缺口是 Least-to-Most：先列出从易到难的子问题序列，再多次查询并把子答案回填。本课写这一分解—回填协议，不重讲图上的合流。它针对组合深度外推，而不是一般的「让我们逐步想」。后课 PAL 默认：能写成程序执行时优先卸给解释器。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>许多基准的难度来自 <em>深度</em> 而不是新概念。SCAN 式指令、最后字母拼接、多步数学应用题，短实例上 CoT 已经能做，长度一加就断。原因是单次生成要把整条组合计划记在正在写的前缀里，早期子目标的结果没有被当成独立的、已核对的事实钉住。后面的步骤在尚未稳定的中间句上继续写，组合误差相乘。</p><p>Least-to-Most 要回答的是：分解能否单独示范、求解能否条件于已给出的子答案，从而使模型在测试时组合出比示范更长的链。若分解与求解仍捆在同一次解码里，它相对 CoT 没有接口上的差别。关键是 <em>多次调用</em> 与 <em>子答案回填</em>。</p><p><span class="marginnote">术语翻译：「组合深度外推」指示范里只见过短例子，测试时却要处理嵌套更多层的同类问题——像平时只做过三步的证明题，考场上来一道七步的。Least-to-Most 的赌注是：把七步拆成若干个三步以内的小题，每一小步都落在能力圈内。</span></p><h3 id="组合深度不是新技能" tabindex="-1">组合深度不是新技能 <a class="header-anchor" href="#组合深度不是新技能" aria-label="Permalink to &quot;组合深度不是新技能&quot;">​</a></h3><p>设任务由同一套原语反复嵌套。示范长度 \\(\\leq L\\)，测试长度 \\(\\gt L\\)。标准 CoT 要求模型在分布外的深度上一次写对全部中间量。Least-to-Most 要求模型：(1) 把深度 \\(\\gt L\\) 的实例拆成深度更小的子问题；(2) 在每个子问题上表现得像在分布内。第二点通常更容易，因为子问题短；第一点需要示范「如何拆」，拆错则后续全错。因此分解示范的质量决定方法上限。</p><p><span class="marginnote">名字里的 least-to-most 指求解顺序：先解决更小的子问题。不是指提示越写越长就一定更好，也不是课程学习里的训练数据排序。它是推理期的分解—回填协议。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两阶段，通常两套少样本。分解阶段：示范「复杂题 → 有序子问题列表」。列表应从依赖最弱、规模最小的问句开始，最后一项才是原题或最接近原题的问句。求解阶段：对列表中第 \\(t\\) 个问句，上下文包含原题（可选）、子问题 \\(1..t\\)，以及已经得到的答案 \\(a_1,\\ldots,a_{t-1}\\)，模型只输出 \\(a_t\\)。\\(a_t\\) 由宿主解析后写入，下一轮不得让模型重抄或改写旧答案，除非显式做校验失败后的重解。</p><p>子问题必须是可单独回答的问句，而不是「步骤 1：开始思考」这种空标题。数学题上，子问题应是带具体数字的小问；符号任务上，应是更短的输入串。分解阶段可以用一次生成列出全部子问题，也可以边解边拆（先拆下一步）。前者省调用、后者适应中途发现拆错。Zhou 等人主路径接近先列出再依次解。动态再拆更像<a href="/llm/plan-vs-react">规划与反应式</a>的混合，要另设停止条件。</p>',13)),(e(),E(r,null,{default:t(()=>[A(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%8E%9F%E9%A2%98%22%5D%20--%3E%20D%5B%22%E5%88%86%E8%A7%A3%E4%B8%BA%E5%AD%90%E9%97%AE%E9%A2%98%20q1..qk%22%5D%0A%20%20D%20--%3E%20S1%5B%22%E6%B1%82%E8%A7%A3%20q1%20%E2%86%92%20a1%22%5D%0A%20%20S1%20--%3E%20S2%5B%22%E6%B1%82%E8%A7%A3%20q2%20%7C%20a1%22%5D%0A%20%20S2%20--%3E%20SK%5B%22%E6%B1%82%E8%A7%A3%20qk%20%7C%20a1..a(k-1)%22%5D%0A%20%20SK%20--%3E%20A%5B%22%E5%8E%9F%E9%A2%98%E7%AD%94%E6%A1%88%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<h3 id="子答案必须由宿主回填" tabindex="-1">子答案必须由宿主回填 <a class="header-anchor" href="#子答案必须由宿主回填" aria-label="Permalink to &quot;子答案必须由宿主回填&quot;">​</a></h3><p>与 ReAct 的观察一样：中间结果若让模型在同一次生成里「记得自己算过」，就没有钉住。宿主把 \\(a_{t-1}\\) 写成明确的「问 / 答」对，再问 \\(q_t\\)，条件分布才能把 \\(a_{t-1}\\) 当事实而不是当可改写的草稿。解析失败时不要把原始长文本整段塞进下一轮，那会把未规范化的噪声变成后续前提。能执行核对的子问题（算术、代码）应先执行再回填执行结果，这已经靠近 PAL，对数值稳定性通常优于纯自然语言 \\(a_t\\)。</p><p>分解列表的长度要有上限。模型会把简单题拆成十几步空转，或把难题拆成一步从而退回 CoT。提示里应示范「该拆到原语为止、不要拆动词」。线上用最大子问题数切断，切断后把未解部分当最后一问一次求完，并打标以便分析是分解过细还是过粗。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Least-to-Most 改变的是条件化范围。求解 \\(q_t\\) 时，模型不必同时计划 \\(q_{t+1}\\)，也不必在同一条 \\(z\\) 里重算 \\(a_1\\)。已回填的答案相当于把组合的前缀变成上下文中的常数。这降低了单次生成的有效深度，使分布内的短求解被反复使用。分解阶段仍然是一次（对静态列表而言）可能很难的生成：它要在未见过的深度上产出合理的子问题序列。分解可以比求解更依赖大模型或更依赖示范。</p><p>相对 CoT：CoT 的中间量是自由文本步骤，没有强制的问答边界，也没有「只许用已公布的 \\(a_{\\lt t}\\)」。相对 ToT：Least-to-Most 默认不在同一层上分叉，不评估多个候选子问题列表，除非再套搜索。相对 Self-Ask：两者都问后续问题，但 Self-Ask 的后续问往往是为补事实（谁、何时），Least-to-Most 的子问题是同一任务上的更小实例，顺序有难易与依赖约束。</p><p><span class="marginnote">先分解再执行很像规划器，但子问题仍是自然语言问句，不是带 schema 的工具 DAG。不要把 Least-to-Most 写成工作流引擎。它没有并行、没有类型检查，除非宿主额外加。</span></p><p>分解错误为什么「无法被后续逐步补上」，而复核又在哪里把链切断，单独画出来。</p>',8)),(e(),E(r,null,{default:t(()=>[A(s,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20BAD%5B%22%E5%88%86%E8%A7%A3%E7%AC%AC%E4%B8%80%E5%88%80%E5%88%87%E9%94%99%E4%BE%9D%E8%B5%96%E9%A1%BA%E5%BA%8F%22%5D%20--%3E%20A1%5B%22a1%20%E6%88%90%E4%B8%BA%E9%94%99%E8%AF%AF%E5%B8%B8%E6%95%B0%22%5D%0A%20%20A1%20--%3E%20PROP%5B%22%E5%9B%9E%E5%A1%AB%E5%8D%8F%E8%AE%AE%E6%8A%8A%20a1%20%E9%92%89%E8%BF%9B%E5%90%8E%E7%BB%AD%E6%AF%8F%E4%B8%80%E6%AD%A5%22%5D%0A%20%20PROP%20--%3E%20CALC%5B%22%E5%90%8E%E7%BB%AD%E6%AF%8F%E6%AD%A5%E5%9C%A8%E9%94%99%E8%AF%AF%E5%89%8D%E6%8F%90%E4%B8%8A%E8%AE%A1%E7%AE%97%22%5D%0A%20%20CALC%20--%3E%20CHK%7B%22%E6%9C%89%E6%B2%A1%E6%9C%89%E8%AE%BE%E5%A4%8D%E6%A0%B8%E7%8E%AF%E8%8A%82%3F%22%7D%0A%20%20CHK%20--%3E%7C%22%E6%B2%A1%E6%9C%89%22%7C%20OUT%5B%22%E9%94%99%E8%AF%AF%E7%AD%94%E6%A1%88%EF%BC%8C%E4%B8%94%E6%AF%94%E5%8D%95%E9%93%BE%20CoT%20%E6%9B%B4%E9%9A%BE%E6%94%B9%E5%8F%A3%22%5D%0A%20%20CHK%20--%3E%7C%22%E6%9C%80%E5%90%8E%E4%B8%80%E9%97%AE%E7%94%A8%E5%85%A8%E9%83%A8%20a%20%E5%A4%8D%E6%A0%B8%E5%8E%9F%E9%A2%98%22%7C%20CONTRA%5B%22%E5%8F%91%E7%8E%B0%E7%9F%9B%E7%9B%BE%20%E2%86%92%20%E6%95%B4%E8%A1%A8%E9%87%8D%E6%8B%86%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=o('<h3 id="分解错误无法被后续逐步补上" tabindex="-1">分解错误无法被后续逐步补上 <a class="header-anchor" href="#分解错误无法被后续逐步补上" aria-label="Permalink to &quot;分解错误无法被后续逐步补上&quot;">​</a></h3><p>若第一刀把依赖切错——先问了需要后问答案才能定义的量——回填协议会把空洞或错误的 \\(a_1\\) 传下去，后续每步都在错的常数上计算。单链 CoT 至少还能在后文改口；Least-to-Most 默认把 \\(a_1\\) 钉死。缓解：对分解列表做一次合法性检查（每个子问题是否可独立答、是否覆盖原题所需的量）；或在最后一问要求模型用全部 \\(a_{\\lt k}\\) 复核原题，发现矛盾则整表重拆。复核是额外调用，但对组合任务往往比盲目加长 \\(k\\) 值得。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>该方法适合原语稳定、难度主要来自嵌套次数的任务。开放域多跳若「更小的问题」其实是另一件事实检索，应走 <a href="/llm/self-ask">Self-Ask</a> 或检索，而不是假装在做同一技能的更短习题。分解示范会强烈绑定领域：SCAN 的拆法搬不到 GSM8K。多任务系统要么为每类任务准备分解示范，要么接受零样本分解的不稳。</p><p>调用次数随 \\(k\\) 线性增加，延迟同样。能一次 CoT 做对的短题不要强制 Least-to-Most。子答案若含隐私或中间推理，日志与对用户展示要分开。不要和课程学习、从易到难的 <em>训练</em> 顺序混为一谈：原文是提示与多次推理，不更新权重。</p><p><span class="marginnote">数字实例：一道拆成 4 个子问题的题要 1 次分解加 4 次求解，共 5 次调用；第 4 次求解的上下文要装下原题、4 个子问题和前 3 个已回填答案。调用数与上下文长度都随 \\(k\\) 线性涨——这正是「短题不要强制分解」的算术依据。</span></p><p><span class="marginnote">直觉类比：回填相当于把每步算出的结果抄在草稿纸顶端并画上框——后面只能引用这个数，不能趁没注意改它。CoT 的中间结果是流水账，写着写着可能悄悄变卦；「问/答」对把事实钉死。</span></p><p><span class="marginnote">「从易到难」在人类教学里常指题库排序。这里的易是 <em>同一实例内部</em> 的子问题。把数据集先按难度训练不是 Least-to-Most prompting。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Least-to-Most 先分解出有序子问题，再多次求解并把子答案回填进后续上下文。</li><li>它针对组合深度外推：短求解重复使用，长组合靠分解承担。</li><li>子答案必须由宿主钉住；分解错了会沿回填协议传播，且比单链更难改口。</li><li>相对 CoT 是多次调用加问答边界；相对 ToT 默认不分叉；相对 Self-Ask 子问题是更小的同类实例。</li><li>分解示范强绑定领域；调用次数随子问题数线性涨。</li><li>出处：Zhou et al., <em>Least-to-Most Prompting Enables Complex Reasoning in Large Language Models</em>, ICLR 2023。</li></ul>',10))])}const u=n(m,[["render",d]]);export{D as __pageData,u as default};
